import redis
DBS=[int(l.split(':')[0][2:]) for l in redis.Redis(port=6379).execute_command('INFO','keyspace').keys()] if False else None
src0=redis.Redis(port=6379)
DBS=[int(k[2:]) for k in src0.info('keyspace').keys()]
stats={}
for db in DBS:
    s=redis.Redis(port=6379,db=db); d=redis.Redis(port=6380,db=db)
    for k in s.scan_iter(count=1000):
        t=s.type(k).decode()
        pexp=s.execute_command('PEXPIRETIME',k)
        if t=='none': continue
        d.delete(k)
        if t=='string':
            v=s.get(k)
            if v is None: continue
            d.set(k,v)
        elif t=='list':
            v=s.lrange(k,0,-1); d.rpush(k,*v)
        elif t=='set':
            v=list(s.smembers(k)); d.sadd(k,*v)
        elif t=='zset':
            v=s.zrange(k,0,-1,withscores=True); d.zadd(k,{m:sc for m,sc in v})
        elif t=='hash':
            h=s.hgetall(k); d.hset(k,mapping=h)
            f=list(h.keys())
            et=s.execute_command('HPEXPIRETIME',k,'FIELDS',len(f),*f)
            for fld,e in zip(f,et):
                if e>0: d.execute_command('HPEXPIREAT',k,e,'FIELDS',1,fld)
        elif t=='stream':
            info=s.execute_command('XINFO','STREAM',k,'FULL','COUNT',0)
            p=d.pipeline(transaction=False)
            for eid,fields in s.xrange(k,'-','+'):
                p.execute_command('XADD',k,eid,*fields)
            p.execute()
            if info[b'length']==0:
                d.execute_command('XADD',k,'0-1','x','y'); d.execute_command('XDEL',k,'0-1')
            d.execute_command('XSETID',k,info[b'last-generated-id'],'ENTRIESADDED',info[b'entries-added'],'MAXDELETEDID',info[b'max-deleted-entry-id'])
            for g in info[b'groups']:
                args=['XGROUP','CREATE',k,g[b'name'],g[b'last-delivered-id']]
                if g[b'entries-read'] is not None: args+=['ENTRIESREAD',g[b'entries-read']]
                d.execute_command(*args)
                for c in g[b'consumers']:
                    d.execute_command('XGROUP','CREATECONSUMER',k,g[b'name'],c[b'name'])
                owner={}
                for c in g[b'consumers']:
                    for eid,dt,cnt in c[b'pending']:
                        owner[eid]=(c[b'name'],dt,cnt)
                for eid,cons,dt,cnt in g[b'pending']:
                    r=d.execute_command('XCLAIM',k,g[b'name'],cons,0,eid,'TIME',dt,'RETRYCOUNT',cnt,'FORCE','JUSTID')
                    if not r: print('WARN PEL entry not restorable',db,k,g[b'name'],eid)
        else:
            print('UNSUPPORTED',db,k,t); continue
        if pexp>0: d.execute_command('PEXPIREAT',k,pexp)
        elif pexp==-2: d.delete(k)
        stats[(db,t)]=stats.get((db,t),0)+1
print(stats)
