import redis
bad=0
for db in (0,2):
    s=redis.Redis(port=6379,db=db); d=redis.Redis(port=6380,db=db)
    for c in (s,d):
        for cb in ('XRANGE','ZRANGE','XINFO STREAM'): c.response_callbacks.pop(cb,None)
    sk=set(s.scan_iter(count=1000)); dk=set(d.scan_iter(count=1000))
    if sk!=dk: print('keyset diff',db,sk^dk); bad+=1
    for k in sk:
        t=s.type(k)
        if d.type(k)!=t: print('type',k); bad+=1; continue
        t=t.decode()
        e1=s.execute_command('PEXPIRETIME',k); e2=d.execute_command('PEXPIRETIME',k)
        if e1!=e2: print('ttl',k,e1,e2); bad+=1
        if t=='string': a,b=s.get(k),d.get(k)
        elif t=='list': a,b=s.lrange(k,0,-1),d.lrange(k,0,-1)
        elif t=='set': a,b=s.smembers(k),d.smembers(k)
        elif t=='zset': a,b=s.execute_command('ZRANGE',k,0,-1,'WITHSCORES'),d.execute_command('ZRANGE',k,0,-1,'WITHSCORES')
        elif t=='hash':
            a,b=s.hgetall(k),d.hgetall(k)
            f=list(a)
            if a==b and s.execute_command('HPEXPIRETIME',k,'FIELDS',len(f),*f)!=d.execute_command('HPEXPIRETIME',k,'FIELDS',len(f),*f): print('field ttl',k); bad+=1
        elif t=='stream':
            a=s.execute_command('XRANGE',k,'-','+'); b=d.execute_command('XRANGE',k,'-','+')
            def norm(x):
                x=dict(zip(x[::2],x[1::2]))
                keep=[b'length',b'last-generated-id',b'max-deleted-entry-id',b'entries-added',b'recorded-first-entry-id']
                gs=[]
                for g in x[b'groups']:
                    g=dict(zip(g[::2],g[1::2]))
                    cons=sorted([(c[1],c[7],c[9]) for c in g[b'consumers']])
                    gs.append((g[b'name'],g[b'last-delivered-id'],g[b'entries-read'],g[b'lag'],g[b'pel-count'],str(g[b'pending']),str(cons)))
                return [x[i] for i in keep],sorted(gs)
            i1=norm(s.execute_command('XINFO','STREAM',k,'FULL','COUNT',0)); i2=norm(d.execute_command('XINFO','STREAM',k,'FULL','COUNT',0))
            if i1!=i2: print('stream meta',k,i1,i2); bad+=1
        if a!=b: print('value',k); bad+=1
print('mismatches',bad)
